Type instantiate(Scheme s) {
  final replacements = <Type, Type>{};
  Type copy(Type t) {
    t = resolve(t);
    if (t.kind == 'var')
      return s.quantified.contains(t) ? replacements.putIfAbsent(t, fresh) : t;
    return Type(t.kind, [for (final child in t.children) copy(child)]);
  }

  return copy(s.value);
}
